contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address first, address second) public {
        require(true);

        c.SetLogFile(first); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetLogFile(second); bool __rev0 = __ESBMC_reverted(); if (__rev0) { secondReverted = true; } else { secondReverted = false; }

        assert(secondReverted);
    }

    receive() external payable {}
}

